import fs from 'node:fs';
import crypto from 'node:crypto';
import RAPIER from '@dimforge/rapier3d-compat';
import {Model3Physics} from '../src/vehicles/model3/Model3Physics.js';
import {AccelerationMetrics} from '../src/vehicles/model3/AccelerationMetrics.js';
import {VehicleSwitcher} from '../src/vehicles/VehicleSwitcher.js';
import {createWorld} from '../src/physics/PhysicsWorld.js';

// All measured motion starts from rest and is generated by existing force /
// wheel-torque integration. No test assigns a target rigid-body velocity.
const MODEL3='model3-performance-2018',DT=1/120,started=performance.now();
const sourcePaths=['src/vehicle/VehiclePhysics.js','src/vehicles/model3/Model3Config.js','src/vehicles/model3/Model3Powertrain.js','src/vehicles/model3/Model3Physics.js','src/vehicles/model3/AccelerationMetrics.js','src/vehicles/VehicleSwitcher.js'];
const hashes=()=>Object.fromEntries(sourcePaths.map(p=>[p,crypto.createHash('sha256').update(fs.readFileSync(new URL('../'+p,import.meta.url))).digest('hex')]));
const initialHashes=hashes(),groups={performance:[],handling:[],switching:[]};
async function test(group,name,fn){
  const checks=[];const check=(condition,message)=>checks.push({passed:!!condition,message});
  const start=performance.now();let measurements,error;
  try{measurements=await fn(check);}catch(e){error=e.stack;checks.push({passed:false,message:e.message});}
  const result={name,passed:checks.every(c=>c.passed),durationMs:performance.now()-start,checks,measurements,...(error?{error}:{})};
  groups[group].push(result);console.log(result.passed?'PASS':'FAIL',name,...checks.filter(c=>!c.passed).map(c=>c.message));return result;
}
await RAPIER.init();
function flatWorld(){const world=new RAPIER.World({x:0,y:-9.81,z:0});world.timestep=DT;world.integrationParameters.numSolverIterations=8;world.createCollider(RAPIER.ColliderDesc.cuboid(10000,.3,50000).setTranslation(0,-.3,0).setFriction(.8));return world;}
function makeCar(options={}){const world=flatWorld(),car=new Model3Physics(world,options);car.reset({x:0,z:0});for(let i=0;i<240;i++)car.step({});return {world,car};}
const speed=car=>Math.hypot(car.body.linvel().x,car.body.linvel().z)*3.6;
function finite(car){const values=[...Object.values(car.body.translation()),...Object.values(car.body.linvel()),...Object.values(car.body.angvel()),...car.wheels.flatMap(w=>[w.omega,w.angle,w.compression,w.load,w.slip])];if(car.error||!values.every(Number.isFinite))throw Error('Nonfinite physics state: '+JSON.stringify(car.error));}
function advance(car,seconds,input={}){for(let i=0;i<Math.round(seconds/DT);i++){car.step(typeof input==='function'?input(i*DT):input);finite(car);}}
function reach(car,targetKmh,seconds=60){let t=0;while(speed(car)<targetKmh&&t<seconds){car.step({drive:1});finite(car);t+=DT;}if(speed(car)<targetKmh)throw Error(`Could not reach ${targetKmh} km/h within ${seconds}s; actual ${speed(car)}`);return t;}
function yawDegrees(car){const q=car.body.rotation();return Math.atan2(2*(q.w*q.y+q.x*q.z),1-2*(q.y*q.y+q.x*q.x))*180/Math.PI;}
function sample(car){return {timeSeconds:car.time,actualKmh:speed(car),position:car.rootPose().p,headingDegrees:yawDegrees(car),wheelOmega:car.wheels.map(w=>w.omega),wheelSlip:car.wheels.map(w=>w.slip),wheelContact:car.wheels.map(w=>w.contact),wheelLoadN:car.wheels.map(w=>w.load),powertrain:car.drivetrain.telemetry()};}

await test('performance','historical-performance-launch-quarter-mile-and-governed-top-speed',check=>{
  const {world,car}=makeCar({mode:'Performance',soc:.9,payloadKg:75});
  try{
    const metrics=new AccelerationMetrics(car),start=sample(car),trace=[];let maxPower=0,maxTorque=0,maxFront=0,maxRear=0,minY=Infinity,maxY=-Infinity,airSteps=0;
    for(let i=0;i<90*120;i++){
      car.step({drive:1});finite(car);const t=car.drivetrain.telemetry(),y=car.rootPose().p.y;
      maxPower=Math.max(maxPower,t.combinedMotorPowerW);maxTorque=Math.max(maxTorque,t.motorTorqueNm);maxFront=Math.max(maxFront,t.frontMotorPowerW);maxRear=Math.max(maxRear,t.rearMotorPowerW);minY=Math.min(minY,y);maxY=Math.max(maxY,y);if(!car.wheels.some(w=>w.contact))airSteps++;
      if(i%120===119)trace.push({second:(i+1)/120,actualKmh:speed(car),wheelOmega:car.wheels.map(w=>w.omega),distanceM:metrics.distance,powerW:t.combinedMotorPowerW,motorTorqueNm:t.motorTorqueNm});
    }
    const measured=metrics.telemetry();
    const bands=[[80,120],[140,180],[200,230],[240,249]].map(([lo,hi])=>{
      const pairs=trace.slice(1).map((entry,i)=>({actualKmh:entry.actualKmh,accelerationMps2:(entry.actualKmh-trace[i].actualKmh)/3.6,powerW:entry.powerW})).filter(x=>x.actualKmh>=lo&&x.actualKmh<hi);
      return {speedBandKmh:[lo,hi],samples:pairs.length,meanAccelerationMps2:pairs.reduce((s,p)=>s+p.accelerationMps2,0)/Math.max(1,pairs.length),meanMotorPowerW:pairs.reduce((s,p)=>s+p.powerW,0)/Math.max(1,pairs.length)};
    });
    check(car.currentMass===1929,'1854 kg curb + 75 kg payload = 1929 kg');
    check(maxPower<=335565*1.00001,'combined motor mechanical power never exceeds 335565 W');
    check(maxTorque<=638.6*1.00001,'combined motor torque never exceeds 638.6 Nm');
    check(maxFront>30000&&maxRear>30000,'both axles produce measurable positive motor power');
    check(measured.strictFromRestSeconds['60mph']>0&&measured.strictFromRestSeconds['100kmh']>measured.strictFromRestSeconds['60mph'],'60 mph and 100 km/h measured as distinct thresholds');
    check(measured.strictFromRestSeconds['160kmh']>measured.strictFromRestSeconds['100kmh'],'0–160 km/h crossing recorded');
    check(measured.quarter?.strictSeconds>0,'402.336 m crossing recorded');
    check(measured.excludedOneFootSeconds>0&&measured.excludedLegacyThreeMphSeconds>0,'exact 1-foot and legacy 3-mph exclusions separately measured');
    check(measured.legacyThreeMphSeconds['60mph']>2.8&&measured.legacyThreeMphSeconds['60mph']<4.3,'2018 3-mph launch result within broad calibration window around 3.5 s, not a forced timer');
    check(measured.maximumActualKmh>245&&measured.maximumActualKmh<251,'governed top speed is near 155 mph');
    check(airSteps===0,'90 s acceleration on long plane has no uncommanded all-wheel flight');
    check(bands[0].meanAccelerationMps2>bands[2].meanAccelerationMps2,'measured high-speed acceleration declines under limited power/drag');
    return {world:'100 km continuous flat collider, no test-track boundary or terrain',dt:DT,mode:'Performance',initialSOC:start.powertrain.soc,curbMassKg:1854,payloadKg:75,totalMassKg:car.currentMass,friction:car.config.friction.dry,measurement:measured,maximumObservedPowerW:maxPower,maximumObservedMotorTorqueNm:maxTorque,maximumFrontPowerW:maxFront,maximumRearPowerW:maxRear,verticalRangeM:maxY-minY,airSeconds:airSteps*DT,lastTenSecondSpeedChangeKmh:trace.at(-1).actualKmh-trace.at(-11).actualKmh,highSpeedAccelerationBands:bands,trace,halfSecondSamples:metrics.samples,quarterTrapDefinition:'instantaneous horizontal rigid-body speed at 402.336 m; not a timed trap-zone average',historicalComparison:{carAndDriver2018:{legacyThreeMph0to60Seconds:3.5,zeroTo100MphSeconds:8.9,quarterSeconds:12.1,quarterTrapMph:114},simulatorLegacyThreeMph0to60DeltaSeconds:measured.legacyThreeMphSeconds['60mph']-3.5}};
  }finally{world.free();}
});

await test('performance','three-modes-obey-independent-torque-and-power-limits',check=>{
  const outcomes=[];
  for(const mode of ['Standard','Performance','Track']){
    const {world,car}=makeCar({mode,soc:.9});
    try{const metrics=new AccelerationMetrics(car);let power=0,torque=0,front=0,rear=0;
      for(let i=0;i<20*120;i++){car.step({drive:1});finite(car);const t=car.drivetrain.telemetry();power=Math.max(power,t.combinedMotorPowerW);torque=Math.max(torque,t.motorTorqueNm);front=Math.max(front,t.frontMotorPowerW);rear=Math.max(rear,t.rearMotorPowerW);}
      const t=car.drivetrain.telemetry();check(power<=t.combinedPowerLimitW*1.0001,`${mode} respects combined power ceiling`);check(torque<=t.combinedMotorTorqueLimitNm*1.0001,`${mode} respects combined motor torque ceiling`);
      outcomes.push({mode,metrics:metrics.telemetry(),maximumPowerW:power,maximumMotorTorqueNm:torque,maximumFrontPowerW:front,maximumRearPowerW:rear,rearTorqueShare:t.rearTorqueShare,allowedPowerW:t.combinedPowerLimitW,allowedMotorTorqueNm:t.combinedMotorTorqueLimitNm});
    }finally{world.free();}
  }
  check(outcomes[0].metrics.strictFromRestSeconds['100kmh']>outcomes[1].metrics.strictFromRestSeconds['100kmh'],'Standard accelerates more gently than Performance');
  check(outcomes[2].allowedPowerW===outcomes[1].allowedPowerW,'Track receives no additional peak power');
  check(outcomes[2].rearTorqueShare>outcomes[1].rearTorqueShare,'Track uses a different rear torque distribution');return outcomes;
});

await test('performance','low-soc-and-empty-battery-limit-drive-without-speed-assignment',check=>{
  const results=[];
  for(const soc of [0,.03,.9]){
    const {world,car}=makeCar({soc});try{advance(car,8,{drive:1});const s=sample(car);results.push({initialSOC:soc,...s});check(s.powertrain.maximumObservedPowerW<=335565*Math.min(1,soc/.08)+1,`SOC ${soc} respects reduced combined power ceiling`);}finally{world.free();}
  }
  check(results[0].actualKmh<.1,'empty battery does not propel the chassis');check(results[1].actualKmh<results[2].actualKmh,'low SOC reduces actual acceleration');return results;
});

await test('handling','regen-coasting-soc-taper-energy-recovery-and-brake-lights',check=>{
  const outcomes=[];
  for(const soc of [.9,1]){
    const {world,car}=makeCar();try{reach(car,70);car.drivetrain.setSOC(soc);const start=sample(car);let maxRegen=0,brakeLightSteps=0,maxRegenLowSpeed=0;
      for(let i=0;i<6*120;i++){car.step({});finite(car);const t=car.drivetrain.telemetry();maxRegen=Math.max(maxRegen,t.regenMechanicalPowerW);if(t.brakeLights)brakeLightSteps++;if(speed(car)<2)maxRegenLowSpeed=Math.max(maxRegenLowSpeed,t.regenMechanicalPowerW);}
      outcomes.push({soc,start,end:sample(car),maximumRegenPowerW:maxRegen,brakeLightSeconds:brakeLightSteps*DT,maxRegenLowSpeedW:maxRegenLowSpeed});
    }finally{world.free();}
  }
  check(outcomes[0].end.actualKmh<outcomes[0].start.actualKmh-15,'releasing accelerator produces meaningful regen deceleration');
  check(outcomes[0].end.powertrain.recoveredWh>outcomes[0].start.powertrain.recoveredWh,'regen returns measured electrical energy');
  check(outcomes[0].brakeLightSeconds>0,'deceleration threshold illuminates brake lamps');
  check(outcomes[1].maximumRegenPowerW<outcomes[0].maximumRegenPowerW*.1,'near-full SOC suppresses regen');
  return outcomes;
});

await test('handling','regen-fades-near-zero-and-preserves-low-speed-stop-stability',check=>{
  const {world,car}=makeCar();try{reach(car,15);let maxAbove10Kmh=0,maxBelow2Kmh=0,below2Samples=0,last=sample(car),seconds=0;const trace=[];
    while(seconds<20&&speed(car)>.3){car.step({});finite(car);seconds+=DT;const p=car.drivetrain.telemetry(),actual=speed(car);if(actual>10)maxAbove10Kmh=Math.max(maxAbove10Kmh,p.regenMechanicalPowerW);if(actual<2){maxBelow2Kmh=Math.max(maxBelow2Kmh,p.regenMechanicalPowerW);below2Samples++;}if(Math.round(seconds/DT)%120===0)trace.push({second:seconds,actualKmh:actual,regenPowerW:p.regenMechanicalPowerW,regenAvailableScale:p.regenAvailableScale});last=sample(car);}
    check(below2Samples>0,'test actually reaches the low-speed regen fade region');check(maxBelow2Kmh<maxAbove10Kmh*.3,'regen power fades as wheel speed approaches zero');check(last.actualKmh<.3,'vehicle settles without an unstable low-speed oscillation');return{maxAbove10KmhRegenW:maxAbove10Kmh,maxBelow2KmhRegenW:maxBelow2Kmh,below2Samples,elapsedSeconds:seconds,end:last,trace};
  }finally{world.free();}
});

for(const surface of ['dry','wet','gravel','ice'])await test('handling',`surface-${surface}-traction-control-and-independent-wheel-loads`,check=>{
  const {world,car}=makeCar();try{car.surface=surface;let maxSlip=0,tcsSteps=0,minContact=4,maxLoad=0;const trace=[];
    for(let i=0;i<12*120;i++){car.step({drive:1});finite(car);const t=car.drivetrain.telemetry();maxSlip=Math.max(maxSlip,...car.wheels.map(w=>Math.abs(w.slip)));if(t.tcsActive)tcsSteps++;minContact=Math.min(minContact,car.wheels.filter(w=>w.contact).length);maxLoad=Math.max(maxLoad,...car.wheels.map(w=>w.load));if(i%120===119)trace.push(sample(car));}
    check(speed(car)>8,`${surface} remains driveable by forces`);check(minContact>=2,`${surface} retains support on flat ground`);check(maxLoad<=car.currentMass*9.81*car.config.maxWheelLoadG/4+.1,'wheel loads remain bounded');
    if(surface==='ice')check(tcsSteps>0,'ice launch invokes real slip-based TCS');
    return {surface,mu:car.config.friction[surface],actualFinalKmh:speed(car),maximumAbsoluteSlip:maxSlip,tcsActiveSeconds:tcsSteps*DT,minimumContactWheels:minContact,maximumWheelLoadN:maxLoad,trace};
  }finally{world.free();}
});

await test('handling','ice-tcs-on-off-comparison-measures-wheelspin-instead-of-only-a-flag',check=>{
  const outcomes=[];for(const enabled of [true,false]){const {world,car}=makeCar();try{car.surface='ice';car.drivetrain.tcsEnabled=enabled;let slipSum=0,peakSlip=0,spinSamples=0;for(let i=0;i<8*120;i++){car.step({drive:1});finite(car);for(const w of car.wheels){const value=Math.abs(w.slip);slipSum+=value;peakSlip=Math.max(peakSlip,value);if(value>.5)spinSamples++;}}outcomes.push({tcsEnabled:enabled,actualKmh:speed(car),meanAbsoluteSlip:slipSum/(8*120*4),peakAbsoluteSlip:peakSlip,over50PercentSlipFraction:spinSamples/(8*120*4),end:sample(car)});}finally{world.free();}}
  check(outcomes[0].meanAbsoluteSlip<outcomes[1].meanAbsoluteSlip*.5,'TCS reduces measured mean wheelspin by at least half');check(outcomes[0].peakAbsoluteSlip<outcomes[1].peakAbsoluteSlip,'TCS reduces peak wheelspin on ice');return outcomes;
});

for(const surface of ['dry','wet','ice'])await test('handling',`abs-emergency-braking-${surface}-from-100kmh`,check=>{
  const outcomes=[];
  for(const absEnabled of [true,false]){
    const {world,car}=makeCar();try{reach(car,100);car.surface=surface;advance(car,.05,{drive:1});car.drivetrain.absEnabled=absEnabled;const start=sample(car);let t=0,absSteps=0,maxLockDuration=0,lockDuration=0,minPressure=1,maxSlip=0,lockedWheelSamples=0,eligibleWheelSamples=0,blendExcessNm=0;const trace=[];
      while(speed(car)>.5&&t<65){car.step({brake:1});finite(car);t+=DT;const p=car.drivetrain.telemetry();if(p.absActive.some(Boolean))absSteps++;minPressure=Math.min(minPressure,...p.absPressure);maxSlip=Math.max(maxSlip,...car.wheels.map(w=>Math.abs(w.slip)));const locked=car.wheels.every(w=>Math.abs(w.omega)<.2)&&speed(car)>10;lockDuration=locked?lockDuration+DT:0;maxLockDuration=Math.max(maxLockDuration,lockDuration);
        if(speed(car)>10)for(const w of car.wheels){eligibleWheelSamples++;if(w.slip<-.8)lockedWheelSamples++;}
        for(let i=0;i<4;i++){const request=car.drivetrain.wheelRequest(i);blendExcessNm=Math.max(blendExcessNm,Math.abs(request.regenTorque)+request.brakeTorque-car.config.brakeTorque*(i<2?.6:.4)*2*p.absPressure[i]);}
        if(Math.round(t/DT)%120===0)trace.push(sample(car));
      }
      const end=sample(car);check(end.actualKmh<=.5,`ABS ${absEnabled?'on':'off'} braking reaches less than 0.5 km/h`);check(!car.thrusters,'Model 3 has no jet assistance');
      outcomes.push({absEnabled,surface,friction:car.config.friction[surface],start,end,stopSeconds:t,stoppingDistanceM:Math.hypot(end.position.x-start.position.x,end.position.z-start.position.z),absActiveSeconds:absSteps*DT,minimumABSScale:minPressure,maximumSlip:maxSlip,maximumAllWheelLockSeconds:maxLockDuration,lockedWheelSampleFraction:lockedWheelSamples/Math.max(1,eligibleWheelSamples),lockedWheelSamples,eligibleWheelSamples,lockDefinition:'wheel slip < -0.8 while actual chassis speed > 10 km/h',maximumRegenHydraulicBlendExcessNm:blendExcessNm,trace});
    }finally{world.free();}
  }
  const [enabled,disabled]=outcomes;
  check(enabled.absActiveSeconds>0,'ABS modulation actually activates');check(enabled.minimumABSScale<.98,'hydraulic/regen pressure is reduced while slipping');check(enabled.maximumAllWheelLockSeconds<2,'four wheels do not stay locked for 2 seconds above 10 km/h');
  check(enabled.lockedWheelSampleFraction<disabled.lockedWheelSampleFraction,'ABS reduces measured wheel-lock sample fraction compared with disabled ABS');
  check(enabled.lockedWheelSampleFraction<.10,'ABS keeps severe wheel locking below 10% of wheel samples above 10 km/h');
  check(enabled.maximumRegenHydraulicBlendExcessNm<.001,'straight braking regen and hydraulic complement receive pressure only once');
  return {...enabled,disabledReference:disabled,comparison:{lockedWheelFractionDifference:enabled.lockedWheelSampleFraction-disabled.lockedWheelSampleFraction,stopDistanceDifferenceM:enabled.stoppingDistanceM-disabled.stoppingDistanceM,stopTimeDifferenceSeconds:enabled.stopSeconds-disabled.stopSeconds,note:'ABS is judged by wheel locking and control, not by assuming it must always shorten stopping distance in this tire model.'}};
});

await test('handling','reverse-regen-and-abs-use-motion-normalized-slip',check=>{
  const {world,car}=makeCar();try{advance(car,6,{drive:-1});const before=sample(car);check(car.forwardSpeed()<-3,'normal reverse torque moves chassis backwards');let active=0,minPressure=1;for(let i=0;i<10*120&&speed(car)>.5;i++){car.step({brake:1});finite(car);const p=car.drivetrain.telemetry();if(p.absActive.some(Boolean))active++;minPressure=Math.min(minPressure,...p.absPressure);}check(speed(car)<.5,'reverse braking stops chassis');return {before,after:sample(car),absActiveSeconds:active*DT,minimumABSScale:minPressure};}finally{world.free();}
});

for(const direction of [-1,1])await test('handling',`grounded-steering-${direction>0?'left':'right'}-from-100kmh`,check=>{
  const {world,car}=makeCar();try{reach(car,100);const before=sample(car);let peakRoll=0,airSteps=0,maxLateralSlip=0;for(let i=0;i<3*120;i++){car.step({drive:.12,steer:direction});finite(car);peakRoll=Math.max(peakRoll,Math.abs(car.telemetry().rollDegrees));if(!car.wheels.some(w=>w.contact))airSteps++;maxLateralSlip=Math.max(maxLateralSlip,...car.wheels.map(w=>Math.abs(w.lateralSlip)));}const after=sample(car);check(after.headingDegrees*direction>12,'physical yaw responds to correct steering sign');check((after.position.x-before.position.x)*direction>3,'chassis moves toward commanded side');check(car.wheels.slice(0,2).every(w=>w.steer*direction>0),'both front wheel angles have correct sign');check(airSteps===0,'ordinary turn does not spontaneously launch all wheels');check(peakRoll<15,'ordinary steering does not roll over');return{before,after,peakRollDegrees:peakRoll,airSeconds:airSteps*DT,maximumLateralSlipMps:maxLateralSlip};}finally{world.free();}
});

await test('handling','continuous-slalom-track-mode-and-load-transfer',check=>{
  const outcomes=[];for(const mode of ['Performance','Track']){const {world,car}=makeCar({mode});try{reach(car,80);let esc=0,tcs=0,maxSlip=0,loadSpread=0,peakRoll=0,air=0;const yaw=[];for(let i=0;i<10*120;i++){car.step({drive:.18,steer:Math.sin(i*DT*1.1)*.65});finite(car);const p=car.drivetrain.telemetry();if(p.escActive)esc++;if(p.tcsActive)tcs++;maxSlip=Math.max(maxSlip,...car.wheels.map(w=>Math.abs(w.slip)));loadSpread=Math.max(loadSpread,Math.max(...car.wheels.map(w=>w.load))-Math.min(...car.wheels.map(w=>w.load)));peakRoll=Math.max(peakRoll,Math.abs(car.telemetry().rollDegrees));if(!car.wheels.some(w=>w.contact))air++;if(i%120===119)yaw.push(yawDegrees(car));}check(air===0,`${mode} slalom stays grounded`);check(loadSpread>500,`${mode} cornering transfers wheel load`);check(peakRoll<18,`${mode} remains upright`);outcomes.push({mode,escActiveSeconds:esc*DT,tcsActiveSeconds:tcs*DT,maxSlip,maximumWheelLoadSpreadN:loadSpread,peakRollDegrees:peakRoll,airSeconds:air*DT,headingSamples:yaw,end:sample(car)});}finally{world.free();}}return outcomes;
});

await test('handling','moderate-slalom-performance-and-track-within-normal-tire-budget',check=>{
  const outcomes=[];
  for(const mode of ['Performance','Track']){const {world,car}=makeCar({mode});try{reach(car,60);let esc=0,maxSlip=0,maxSideslip=0,peakRoll=0,air=0;const trace=[];
    for(let i=0;i<10*120;i++){car.step({drive:.11,steer:Math.sin(i*DT*.9)*.25});finite(car);const p=car.drivetrain.telemetry(),q=car.body.rotation(),vel=car.body.linvel();if(p.escActive)esc++;maxSlip=Math.max(maxSlip,...car.wheels.map(w=>Math.abs(w.slip)));const f={x:2*(q.x*q.z+q.w*q.y),z:1-2*(q.y*q.y+q.x*q.x)},l={x:1-2*(q.y*q.y+q.z*q.z),z:2*(q.x*q.z-q.w*q.y)},sideslip=Math.atan2(vel.x*l.x+vel.z*l.z,Math.max(2,Math.abs(vel.x*f.x+vel.z*f.z)))*180/Math.PI;maxSideslip=Math.max(maxSideslip,Math.abs(sideslip));peakRoll=Math.max(peakRoll,Math.abs(car.telemetry().rollDegrees));if(!car.wheels.some(w=>w.contact))air++;if(i%120===119)trace.push({second:(i+1)/120,actualKmh:speed(car),yawDegrees:yawDegrees(car),sideslipDegrees:sideslip,slips:car.wheels.map(w=>w.slip)});}
    check(air===0,`${mode} moderate slalom stays grounded`);check(maxSideslip<20,`${mode} moderate inputs avoid uncontrolled body sideslip`);check(peakRoll<12,`${mode} moderate slalom remains upright`);outcomes.push({mode,initialSpeedKmh:60,steeringInputAmplitude:.25,throttle:.11,maximumSideslipDegrees:maxSideslip,maximumWheelSlip:maxSlip,peakRollDegrees:peakRoll,airSeconds:air*DT,escActiveSeconds:esc*DT,trace});
  }finally{world.free();}}
  return {normalInputResults:outcomes,aggressiveInputCaveat:'The separate 80 km/h, 65% steering stress trace exceeds the friction-limited turn radius and may spin in Track; it validates finite physical behavior and load transfer, not controllability at those excessive inputs.'};
});

for(const scenario of ['suspension-hill','speed-bumps'])await test('handling',`existing-test-track-${scenario}`,async check=>{
  const {world}=await createWorld();const car=new Model3Physics(world);try{car.reset(scenario==='suspension-hill'?{x:-35,z:0}:{x:0,z:-85});advance(car,2);const start=sample(car);let minY=Infinity,maxY=-Infinity,maxRoll=0,air=0,maxCompression=-Infinity,minCompression=Infinity;const seconds=10;
    for(let i=0;i<seconds*120;i++){car.step({drive:scenario==='suspension-hill'?.26:.19});finite(car);const p=car.rootPose().p;minY=Math.min(minY,p.y);maxY=Math.max(maxY,p.y);maxRoll=Math.max(maxRoll,Math.abs(car.telemetry().rollDegrees));if(!car.wheels.some(w=>w.contact))air++;maxCompression=Math.max(maxCompression,...car.wheels.map(w=>w.compression));minCompression=Math.min(minCompression,...car.wheels.map(w=>w.compression));}
    const end=sample(car);check(end.position.z>(scenario==='suspension-hill'?55:-25),'vehicle actually crosses the intended physical feature');check(maxY<(scenario==='suspension-hill'?3:1),'feature does not cause an extreme unintended launch');check(minY>-.08,'chassis does not sink below the test-track ground');check(maxCompression<=.0200001&&minCompression>=-.0900001,'wheel motion respects selected mesh-safe suspension limits');check(maxRoll<20,'vehicle stays upright over feature');if(scenario==='suspension-hill')check(maxY>.35,'physical ramp raises the actual chassis');return {scenario,start,end,minRootY:minY,maxRootY:maxY,peakRollDegrees:maxRoll,airSeconds:air*DT,maxCompressionM:maxCompression,minCompressionM:minCompression};
  }finally{world.free();}
});

await test('switching','twenty-four-safe-switches-with-flying-chaos-crash-track-and-test-state',async check=>{
  const world=flatWorld();const wall=world.createCollider(RAPIER.ColliderDesc.cuboid(5,1,.4).setTranslation(50,1,20));const baseColliders=world.colliders.len();const phases=[],mounts=[],unmounts=[];let activeMetrics=null;
  const switcher=new VehicleSwitcher(world,{prepare:async id=>({id,nodeTestsOnly:true}),onPhase:(phase,id,error)=>phases.push({phase,id,error:error?.message}),unmount:session=>{unmounts.push({id:session.id,handle:session.vehicle.body.handle,input:{...session.vehicle.currentInput}});activeMetrics=null;},mount:session=>{mounts.push(session.id);if(session.id===MODEL3)activeMetrics=new AccelerationMetrics(session.vehicle);}});
  const contexts=[];
  try{
    await switcher.switchTo('roadster');
    for(let i=0;i<24;i++){
      const previous=switcher.active,car=previous.vehicle;let context,wallContacts=null;
      if(previous.id==='roadster'){
        if(i%4===0){context='Roadster flying with attitude jets';car.reset({x:0,z:0,y:8});previous.thrusters.arm();advance(car,.4,{lift:1,pitch:.3,yaw:.3});}
        else{context='Roadster Chaos/infinite/high-thrust/hover';car.reset({x:0,z:0,y:12});previous.thrusters.setMode('Chaos');previous.thrusters.infiniteGas=true;previous.thrusters.highThrust=true;previous.thrusters.toggleHover();advance(car,.4,{boost:true,lift:1,roll:.2});}
      }else if(i%6===1){context='Model 3 after physical wall impact';car.reset({x:50,z:0});advance(car,6,{drive:.55});wallContacts=0;for(let j=0;j<car.body.numColliders();j++)world.contactPair(car.body.collider(j),wall,m=>wallContacts+=m.numContacts());check(wallContacts>0,`switch ${i+1} crash case actually touches the physical wall`);}
      else if(i%6===3){context='Model 3 Track with active slip';car.drivetrain.setMode('Track');advance(car,2,{drive:1,steer:.7,handbrake:true});}
      else{context='Model 3 after completed acceleration/quarter-mile test';advance(car,14,{drive:1});check(activeMetrics.state==='complete',`switch ${i+1} happens after a completed physical quarter-mile test`);}
      const before={context,id:previous.id,bodyHandle:car.body.handle,speedKmh:speed(car),wallContactPoints:wallContacts,metricsState:activeMetrics?.state,thrusters:previous.thrusters?{thrustN:previous.thrusters.thrustNewtons,mode:previous.thrusters.mode,hover:previous.thrusters.hover,infinite:previous.thrusters.infiniteGas}:null};
      const target=previous.id==='roadster'?MODEL3:'roadster',next=await switcher.switchTo(target);
      const record=switcher.switches.at(-1);check(record.oldHandleRemoved,`switch ${i+1} removed old rigid body before constructing next (handle reuse allowed)`);check(car.disposed,`switch ${i+1} disposed old controller`);check(car.preStepProducers.length===0&&car.forceProducers.length===0&&car.postStepProducers.length===0,`switch ${i+1} removed old physics hooks`);
      check(world.bodies.len()===1,`switch ${i+1} has exactly one dynamic chassis`);check(world.colliders.len()===baseColliders+7,`switch ${i+1} has baseline plus seven vehicle colliders`);
      check(speed(next.vehicle)<.001,`switch ${i+1} starts with zero linear velocity`);check(Object.values(next.vehicle.body.angvel()).every(v=>Math.abs(v)<1e-12),`switch ${i+1} starts with zero angular velocity`);check(next.vehicle.wheels.every(w=>w.omega===0&&w.angle===0&&w.steer===0&&w.compression===0),`switch ${i+1} resets all wheel/contact animation state`);
      check(Object.keys(next.vehicle.currentInput).length===0,`switch ${i+1} clears previous vehicle input`);
      check([...Object.values(next.vehicle.body.userForce()),...Object.values(next.vehicle.body.userTorque())].every(v=>Math.abs(v)<1e-12),`switch ${i+1} starts without accumulated forces or torques`);
      if(previous.thrusters)check(!previous.thrusters.enabled&&previous.thrusters.thrustNewtons===0&&previous.thrusters.nozzles.every(n=>n.thrust===0&&n.valve===0),`switch ${i+1} stops all old jets before disposal`);
      if(target===MODEL3){check(next.thrusters===null&&!next.vehicle.thrusters,`switch ${i+1} Model 3 has no jet system`);check(next.vehicle.drivetrain.mode==='Performance',`switch ${i+1} Model 3 does not inherit Track mode`);check(activeMetrics.state==='ready',`switch ${i+1} acceleration metrics reset`);}
      else{check(next.thrusters.mode==='Stabilized'&&!next.thrusters.hover&&!next.thrusters.flightArmed&&!next.thrusters.infiniteGas&&!next.thrusters.highThrust,`switch ${i+1} Roadster flight flags reset`);check(next.thrusters.fuel.mass===160&&next.thrusters.thrustNewtons===0,`switch ${i+1} Roadster tank and nozzle state are fresh`);}
      contexts.push({index:i+1,before,after:{id:target,bodyHandle:next.vehicle.body.handle,bodies:world.bodies.len(),colliders:world.colliders.len(),oldHandleRemoved:record.oldHandleRemoved,speedKmh:speed(next.vehicle),input:next.vehicle.currentInput}});
    }
    check(mounts.length===25&&unmounts.length===24,'one mount per creation and one unmount per replaced controller');
    const records=[...switcher.switches];switcher.dispose();check(world.bodies.len()===0&&world.colliders.len()===baseColliders,'final disposal returns physics world to collider baseline');
    return {scope:'Node/Rapier sessions and callbacks only; no GLTF renderer, UI events, RAF, or GPU-memory claim',continuousSwitches:24,baseColliders,expectedActiveColliders:baseColliders+7,records,contexts,phases,mounts:mounts.length,unmountsAfterFinalDispose:unmounts.length,finalBodies:world.bodies.len(),finalColliders:world.colliders.len()};
  }finally{switcher.dispose();world.free();}
});

